def ordinal_word(n):
    words = {1: "first", 2: "second", 3: "third", 4: "fourth", 5: "fifth",
             6: "sixth", 7: "seventh", 8: "eighth", 9: "ninth",
             10: "tenth", 11: "eleventh", 12: "twelfth"}
    if n in words:
        return words[n]
    return f"{n}th"

def format_list_with_and(items):
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    return ", ".join(items[:-1]) + f", and {items[-1]}"

def render_template(template, values):
    result = template
    for k, v in values.items():
        result = result.replace('{' + k + '}', str(v))
    return result

def render_template_default(template, values, default):
    import re
    def repl(m):
        key = m.group(1)
        return str(values.get(key, default))
    return re.sub(r'\{(\w+)\}', repl, template)

def mail_merge(template, records):
    results = []
    for record in records:
        s = template
        for k, v in record.items():
            s = s.replace('{' + k + '}', str(v))
        results.append(s)
    return results

def fill_blanks(template, words):
    result = template
    for w in words:
        result = result.replace('___', w, 1)
    return result

def build_csv_line(fields):
    parts = []
    for f in fields:
        if ',' in f or '"' in f:
            parts.append('"' + f.replace('"', '""') + '"')
        else:
            parts.append(f)
    return ','.join(parts)

def capitalize_sentence(s):
    if not s:
        return s
    return s[0].upper() + s[1:]

def capitalize_sentences(text):
    sentences = text.split('. ')
    capped = [s[0].upper() + s[1:] if s else s for s in sentences]
    return '. '.join(capped)

def collapse_whitespace(s):
    import re
    return re.sub(r'\s+', ' ', s).strip()
